    { id=20732, tab=2, tier=3, col=2, name="Нечестивая сила", icon="spell_shadow_shadowworddominate", maxRank=5, prereqTalent=0, prereqPoints=15, wired=true, tooltip={ "Увеличивает урон от атак в ближнем бою демона Бездны, суккуба, охотника Скверны и стража Скверны, а также от \"Огненной стрелы\" беса на 4%.", "Увеличивает урон от атак в ближнем бою демона Бездны, суккуба, охотника Скверны и стража Скверны, а также от \"Огненной стрелы\" беса на 8%.", "Увеличивает урон от атак в ближнем бою демона Бездны, суккуба, охотника Скверны и стража Скверны, а также от \"Огненной стрелы\" беса на 12%.", "Увеличивает урон от атак в ближнем бою демона Бездны, суккуба, охотника Скверны и стража Скверны, а также от \"Огненной стрелы\" беса на 16%.", "Увеличивает урон от атак в ближнем бою демона Бездны, суккуба, охотника Скверны и стража Скверны, а также от \"Огненной стрелы\" беса на 20%." }, grant={ [1]=18769, [2]=18770, [3]=18771, [4]=18772, [5]=18773 } },
    { id=20733, tab=2, tier=4, col=0, name="Улучшенное порабощение демона", icon="spell_shadow_enslavedemon", maxRank=2, prereqTalent=0, prereqPoints=20, wired=true, tooltip={ "Уменьшает штраф к скорости атаки и применения заклинаний от \"Порабощения демона\" на 5%, а также снижает вероятность сопротивления на 5%.", "Уменьшает штраф к скорости атаки и применения заклинаний от \"Порабощения демона\" на 10%, а также снижает вероятность сопротивления на 10%." } },
    { id=20734, tab=2, tier=4, col=1, name="Демоническое жертвоприношение", icon="spell_shadow_psychicscream", maxRank=1, prereqTalent=0, prereqPoints=20, wired=true, tooltip={ "При активации приносит в жертву призванного демона и дает вам на 30 мин. эффект, который снимается при вызове нового демона. Бес: увеличивает урон от огня на 15%. Демон Бездны: восполняет 2% общего запаса здоровья раз в 4 сек. Суккуб: увеличивает урон от темной магии на 15%. Охотник Скверны: восполняет 3% общего запаса маны раз в 4 сек. Страж Скверны: увеличивает урон от темной магии на 10% и восполняет 2% общего запаса маны раз в 4 сек." }, grant={ [1]=948552 } },
    { id=20735, tab=2, tier=4, col=3, name="Мастер кудесник", icon="inv_ammo_firetar", maxRank=2, prereqTalent=0, prereqPoints=20, wired=true, tooltip={ "Увеличивает бонусный урон от камней огня и усиливает их эффект на 15%, а также увеличивает бонус к рейтингу критического эффекта заклинаний от камней чар на 15%.", "Увеличивает бонусный урон от камней огня и усиливает их эффект на 30%, а также увеличивает бонус к рейтингу критического эффекта заклинаний от камней чар на 30%." } },
    { id=20736, tab=2, tier=5, col=0, name="Манакорм", icon="spell_shadow_manafeed", maxRank=3, prereqTalent=0, prereqPoints=25, wired=true, tooltip={ "Когда вы получаете ману с помощью \"Похищения маны\" или \"Жизнеотвода\", ваш прислужник получает 33% полученной маны.", "Когда вы получаете ману с помощью \"Похищения маны\" или \"Жизнеотвода\", ваш прислужник получает 66% полученной маны.", "Когда вы получаете ману с помощью \"Похищения маны\" или \"Жизнеотвода\", ваш прислужник получает 100% полученной маны." } },
    { id=20737, tab=2, tier=5, col=2, name="Мастер-демонолог", icon="spell_shadow_shadowpact", maxRank=5, prereqTalent=20732, prereqPoints=25, wired=true, tooltip={ "Дает чернокнижнику и призванному демону эффект, действующий, пока активен демон. Бес: снижает уровень угрозы на 4%. Демон Бездны: уменьшает получаемый физический урон на 2%. Суккуб: увеличивает наносимый урон на 2%. Охотник Скверны: повышает сопротивление всем видам магии на 0,2 за каждый уровень. Страж Скверны: увеличивает наносимый урон на 1% и повышает сопротивление всем видам магии на 0,1 за каждый уровень.", "Дает чернокнижнику и призванному демону эффект, действующий, пока активен демон. Бес: снижает уровень угрозы на 8%. Демон Бездны: уменьшает получаемый физический урон на 4%. Суккуб: увеличивает наносимый урон на 4%. Охотник Скверны: повышает сопротивление всем видам магии на 0,4 за каждый уровень. Страж Скверны: увеличивает наносимый урон на 2% и повышает сопротивление всем видам магии на 0,2 за каждый уровень.", "Дает чернокнижнику и призванному демону эффект, действующий, пока активен демон. Бес: снижает уровень угрозы на 12%. Демон Бездны: уменьшает получаемый физический урон на 6%. Суккуб: увеличивает наносимый урон на 6%. Охотник Скверны: повышает сопротивление всем видам магии на 0,6 за каждый уровень. Страж Скверны: увеличивает наносимый урон на 3% и повышает сопротивление всем видам магии на 0,3 за каждый уровень.", "Дает чернокнижнику и призванному демону эффект, действующий, пока активен демон. Бес: снижает уровень угрозы на 16%. Демон Бездны: уменьшает получаемый физический урон на 8%. Суккуб: увеличивает наносимый урон на 8%. Охотник Скверны: повышает сопротивление всем видам магии на 0,8 за каждый уровень. Страж Скверны: увеличивает наносимый урон на 4% и повышает сопротивление всем видам магии на 0,4 за каждый уровень.", "Дает чернокнижнику и призванному демону эффект, действующий, пока активен демон. Бес: снижает уровень угрозы на 20%. Демон Бездны: уменьшает получаемый физический урон на 10%. Суккуб: увеличивает наносимый урон на 10%. Охотник Скверны: повышает сопротивление всем видам магии на 1 за каждый уровень. Страж Скверны: увеличивает наносимый урон на 5% и повышает сопротивление всем видам магии на 0,5 за каждый уровень." } },
    { id=20738, tab=2, tier=6, col=0, name="Демоническая устойчивость", icon="spell_shadow_demonicfortitude", maxRank=3, prereqTalent=0, prereqPoints=30, wired=true, tooltip={ "Снижение на 1% вероятности получения критического урона от атак ближнего боя и заклинаний, а также снижение на 5% урона, получаемого призванным демоном.", "Снижение на 2% вероятности получения критического урона от атак ближнего боя и заклинаний, а также снижение на 10% урона, получаемого призванным демоном.", "Снижение на 3% вероятности получения критического урона от атак ближнего боя и заклинаний, а также снижение на 15% урона, получаемого призванным демоном." }, grant={ [1]=30319, [2]=30320, [3]=30321 } },
    { id=20739, tab=2, tier=6, col=1, name="Связка души", icon="spell_shadow_gathershadows", maxRank=1, prereqTalent=20734, prereqPoints=30, wired=true, tooltip={ "Пока эффект действует, 20% урона, получаемого чернокнижником, передается его бесу, демону Бездны, суккубу, охотнику Скверны, стражу Скверны или порабощенному демону. Передаваемый урон нельзя предотвратить. Кроме того, демон и его хозяин наносят на 5% больше урона. Эффект длится, пока демон находится рядом с хозяином и подчиняется ему." }, grant={ [1]=948550 } },
